// AdminServiceHandler is an implementation of the probe.v1.AdminService service.
type AdminServiceHandler interface {
	// 用管理员密码换取会话 cookie（Set-Cookie 在响应头里）。
	Login(context.Context, *connect.Request[v1.LoginRequest]) (*connect.Response[v1.LoginResponse], error)
	// 作废当前会话并清除 cookie。
	Logout(context.Context, *connect.Request[v1.LogoutRequest]) (*connect.Response[v1.LogoutResponse], error)
	// 列出未绝对过期且未空闲过期的会话，按创建时刻倒序、同刻按 id 升序。
	// API token 不能管理其它凭据，因此不能列出或撤销会话。
	ListSessions(context.Context, *connect.Request[v1.ListSessionsRequest]) (*connect.Response[v1.ListSessionsResponse], error)
	// 撤销指定会话；撤销当前会话时同时清 cookie，等同登出。
	// 不存在或已过期的 id 也成功，便于在响应丢失后安全重试。
	RevokeSession(context.Context, *connect.Request[v1.RevokeSessionRequest]) (*connect.Response[v1.RevokeSessionResponse], error)
	ListNodes(context.Context, *connect.Request[v1.ListNodesRequest]) (*connect.Response[v1.ListNodesResponse], error)
	// 建节点并返回其 token；明文只在此处返回一次。
	CreateNode(context.Context, *connect.Request[v1.CreateNodeRequest]) (*connect.Response[v1.CreateNodeResponse], error)
	// 整体替换可编辑字段（名称、是否公开、备注、周期重置日、离线宽限期、计费与到期）。计费字段有变化时，
	// 返回之前按新值做一次到期扫描（自动续期推后、到期规则评估），响应里的到期日与 days_left 是扫描之后的值。
	UpdateNode(context.Context, *connect.Request[v1.UpdateNodeRequest]) (*connect.Response[v1.UpdateNodeResponse], error)
	// 删除节点及其全部历史；进程内的实时状态同步清理。
	DeleteNode(context.Context, *connect.Request[v1.DeleteNodeRequest]) (*connect.Response[v1.DeleteNodeResponse], error)
	// 换发 token：旧 token 立即失效，新明文只在此处返回一次。
	RotateNodeToken(context.Context, *connect.Request[v1.RotateNodeTokenRequest]) (*connect.Response[v1.RotateNodeTokenResponse], error)
	// 给出全部节点 id 的新顺序；必须恰好包含每个节点一次。
	ReorderNodes(context.Context, *connect.Request[v1.ReorderNodesRequest]) (*connect.Response[v1.ReorderNodesResponse], error)
	// 开启（或替换）注册窗口，返回一次性 key。
	OpenRegisterWindow(context.Context, *connect.Request[v1.OpenRegisterWindowRequest]) (*connect.Response[v1.OpenRegisterWindowResponse], error)
	CloseRegisterWindow(context.Context, *connect.Request[v1.CloseRegisterWindowRequest]) (*connect.Response[v1.CloseRegisterWindowResponse], error)
	GetRegisterWindow(context.Context, *connect.Request[v1.GetRegisterWindowRequest]) (*connect.Response[v1.GetRegisterWindowResponse], error)
	// 全部节点的实时状态，供轮询；轮询间隔不必短于 report_interval_ms。
	GetSnapshot(context.Context, *connect.Request[v1.GetSnapshotRequest]) (*connect.Response[v1.GetSnapshotResponse], error)
	// 某节点一段时间的历史；级别与步长由 hub 按窗口选定并随数据返回。
	QueryMetrics(context.Context, *connect.Request[v1.QueryMetricsRequest]) (*connect.Response[v1.QueryMetricsResponse], error)
	// 全部节点的流量：hub 累计的总量、当前周期用量、周期起点与下次重置时刻。
	GetTraffic(context.Context, *connect.Request[v1.GetTrafficRequest]) (*connect.Response[v1.GetTrafficResponse], error)
	// 把某节点当前周期的用量覆盖为给定值；总量按同一差值调整且不低于 0，计数器基线不动。
	AdjustTraffic(context.Context, *connect.Request[v1.AdjustTrafficRequest]) (*connect.Response[v1.AdjustTrafficResponse], error)
	// 列出全部探测任务及其分配。
	ListProbeTasks(context.Context, *connect.Request[v1.ListProbeTasksRequest]) (*connect.Response[v1.ListProbeTasksResponse], error)
	// 保存探测任务：id 为 0 即创建，提交整份分配列表。
	SaveProbeTask(context.Context, *connect.Request[v1.SaveProbeTaskRequest]) (*connect.Response[v1.SaveProbeTaskResponse], error)
	// 删除探测任务：不删历史，到期由清理删除。
	DeleteProbeTask(context.Context, *connect.Request[v1.DeleteProbeTaskRequest]) (*connect.Response[v1.DeleteProbeTaskResponse], error)
	// 某节点在窗口内全部任务的探测历史，选级与对齐规则同 QueryMetrics。
	QueryProbes(context.Context, *connect.Request[v1.QueryProbesRequest]) (*connect.Response[v1.QueryProbesResponse], error)
	// 列出规则及其当前节点状态。
	ListAlertRules(context.Context, *connect.Request[v1.ListAlertRulesRequest]) (*connect.Response[v1.ListAlertRulesResponse], error)
	// id 为 0 时创建，否则整体替换规则与作用域、渠道列表。
	SaveAlertRule(context.Context, *connect.Request[v1.SaveAlertRuleRequest]) (*connect.Response[v1.SaveAlertRuleResponse], error)
	// 删除规则与状态；事件与投递记录随规则删除保留；保留期见维护任务。
	DeleteAlertRule(context.Context, *connect.Request[v1.DeleteAlertRuleRequest]) (*connect.Response[v1.DeleteAlertRuleResponse], error)
	// 按事件 id 倒序分页，包含每个事件的投递状态；投递失败只给类别与状态码，原文见 GetAlertDeliveryError。
	ListAlertEvents(context.Context, *connect.Request[v1.ListAlertEventsRequest]) (*connect.Response[v1.ListAlertEventsResponse], error)
	// 一次投递最近一次失败的原文：HTTP 失败时是响应体的前 200 个字符，其余是出站错误文本。hub 不把 URL
	// 写进原文，但响应体由接收方决定：接收方若回显请求路径或头值，这些只写不读的配置也会出现在这里，
	// 这在会话的权限之内。
	// 接收方可能在错误响应里回显收到的请求体，而 webhook 请求体模板里可能放着密钥，所以只对会话开放。
	// 投递不存在时返回 NotFound；没有失败、或类别没有原文时返回空串。
	GetAlertDeliveryError(context.Context, *connect.Request[v1.GetAlertDeliveryErrorRequest]) (*connect.Response[v1.GetAlertDeliveryErrorResponse], error)
	// 不回显凭据本身，但请求体模板、URL 主机名与头名称会回显，模板里可能放着密钥。
	// agent 不需要渠道配置，所以只对会话开放。
	ListNotifyChannels(context.Context, *connect.Request[v1.ListNotifyChannelsRequest]) (*connect.Response[v1.ListNotifyChannelsResponse], error)
	// id 为 0 创建，否则替换；凭据字段为空或省略时保留旧值，删除头用 remove_headers。
	SaveNotifyChannel(context.Context, *connect.Request[v1.SaveNotifyChannelRequest]) (*connect.Response[v1.SaveNotifyChannelResponse], error)
	// 被告警规则引用的渠道不可删除，错误列出引用规则。
	DeleteNotifyChannel(context.Context, *connect.Request[v1.DeleteNotifyChannelRequest]) (*connect.Response[v1.DeleteNotifyChannelResponse], error)
	// 向已保存的渠道同步发送测试消息；不可重试失败返回 FailedPrecondition，可重试返回 Unavailable，文本为错误原文。
	TestNotifyChannel(context.Context, *connect.Request[v1.TestNotifyChannelRequest]) (*connect.Response[v1.TestNotifyChannelResponse], error)
	// 公开页外观：标题、明暗、主色、logo 与自定义 CSS，经 PublicService.GetSite 对外下发。
	GetSettings(context.Context, *connect.Request[v1.GetSettingsRequest]) (*connect.Response[v1.GetSettingsResponse], error)
	// 整体替换外观的五项并回显 hub 实际保存的值。任一项不合约束即 InvalidArgument，错误写明字段、
	// 约束与期望取值，什么都不写入。
	UpdateSettings(context.Context, *connect.Request[v1.UpdateSettingsRequest]) (*connect.Response[v1.UpdateSettingsResponse], error)
	// 库的逻辑大小与每张表的行数，与 probe-hub stats 同一来源。
	GetStorageStats(context.Context, *connect.Request[v1.GetStorageStatsRequest]) (*connect.Response[v1.GetStorageStatsResponse], error)
	// API token 的元数据；明文只在 CreateApiToken 的响应里出现一次，hub 只存哈希。
	ListApiTokens(context.Context, *connect.Request[v1.ListApiTokensRequest]) (*connect.Response[v1.ListApiTokensResponse], error)
	// 建一个只读 API token，以 Authorization: Bearer <token> 调用 ACCESS_READ 方法。
	CreateApiToken(context.Context, *connect.Request[v1.CreateApiTokenRequest]) (*connect.Response[v1.CreateApiTokenResponse], error)
	// 吊销：下一个用它的请求即返回 Unauthenticated，不需要重启 hub。
	DeleteApiToken(context.Context, *connect.Request[v1.DeleteApiTokenRequest]) (*connect.Response[v1.DeleteApiTokenResponse], error)
	// 入口卡片与 hub 构建时嵌入的全部 proto 源文件：不在仓库里的调用方由此取得与 hub 同版本的 schema。
	GetApiReference(context.Context, *connect.Request[v1.GetApiReferenceRequest]) (*connect.Response[v1.GetApiReferenceResponse], error)
}

